dtsPropsFor.PersonSearch:
/** People to search: { id, name, personnelNo } (personnelNo may be null). */
people: { id: string; name: string; personnelNo: string | null }[];
/** Selected person id, or null. */
value: string | null;
onChange: (id: string | null) => void;
/** Defaults to «نام یا شماره پرسنلی را تایپ کنید». */
placeholder?: string;
/** Accessible name when there is no visible <label htmlFor>. */
ariaLabel?: string;
id?: string;
testId: string;
/** Posts the chosen id ('' when none) with a surrounding <form> under this name. */
name?: string;
disabled?: boolean;
/** Max suggestions shown (default 5). */
limit?: number;
/** Characters typed before suggestions appear (default 2). */
minChars?: number;

dtsPropsFor.StatusBadge:
status: "pending" | "approved" | "rejected" | "cancelled" | "awaitingTravel";
/** Display text per status (awaitingTravel falls back to approved's label). */
labels: { pending: string; approved: string; rejected: string; cancelled: string; awaitingTravel?: string };

dtsPropsFor.TriStateToggle:
value: "edit" | "read" | "none";
onChange: (v: "edit" | "read" | "none") => void;
/** Levels the item has: 'RE' all three; 'E' (action) no read-only; 'R' (view-only) no edit. Missing levels render disabled with a tooltip. */
shape: "RE" | "E" | "R";
labels: { edit: string; read: string; none: string; noRead: string; noEdit: string };
/** Accessible name of the group. */
name: string;
testId?: string;

dtsPropsFor.Toaster:
position?: "top-left" | "top-right" | "bottom-left" | "bottom-right" | "top-center" | "bottom-center";
expand?: boolean;
richColors?: boolean;
closeButton?: boolean;
/** Default ms each toast stays (sonner default 4000). */
duration?: number;
visibleToasts?: number;
dir?: "auto" | "rtl" | "ltr";
offset?: string | number;
className?: string;
style?: React.CSSProperties;
